import numpy as np, math
eps=np.finfo(np.float64).eps
x=np.array([0.4,0.3,0.2,0.1]); q=np.array([1.,2.,3.,4.]); q=q/np.linalg.norm(q)
def helmert(D):
    B=np.zeros((D-1,D))
    for i in range(1,D):
        B[i-1,:i]=1/i; B[i-1,i]=-1; B[i-1]*=math.sqrt(i/(i+1))
    return B
def clr(v): L=np.log(v); return L-L.mean()
def qmul(a,b):
    w1,x1,y1,z1=a; w2,x2,y2,z2=b
    return np.array([w1*w2-x1*x2-y1*y2-z1*z2, w1*x2+x1*w2+y1*z2-z1*y2, w1*y2-x1*z2+y1*w2+z1*x2, w1*z2+x1*y2-y1*x2+z1*w2])
def qconj(a): return np.array([a[0],-a[1],-a[2],-a[3]])
def Rq(q):
    w,xx,y,z=q
    return np.array([[1-2*(y*y+z*z),2*(xx*y-z*w),2*(xx*z+y*w)],[2*(xx*y+z*w),1-2*(xx*xx+z*z),2*(y*z-xx*w)],[2*(xx*z-y*w),2*(y*z+xx*w),1-2*(xx*xx+y*y)]])
v=helmert(4)@clr(x)
sand=qmul(qmul(q,np.array([0.,*v])),qconj(q))[1:]
print(eps, float(np.max(np.abs(sand-Rq(q)@v))), float(abs(np.linalg.norm(sand)-np.linalg.norm(v))))
